-- Enterprise permission catalog v4: tabbed, granular permissions + per-user overrides.
CREATE TABLE IF NOT EXISTS permission_groups (
    group_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_code varchar(50) NOT NULL UNIQUE, name_ar varchar(200) NOT NULL, name_en varchar(200) NOT NULL,
    display_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS user_permissions (
    user_id uuid NOT NULL REFERENCES users(user_id), permission_id bigint NOT NULL REFERENCES permissions(permission_id),
    effect boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY(user_id, permission_id)
);
CREATE INDEX IF NOT EXISTS ix_user_permissions_permission ON user_permissions(permission_id);
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS group_code varchar(50) NOT NULL DEFAULT 'SYSTEM';
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS feature_code varchar(100) NOT NULL DEFAULT '';
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS operation_code varchar(50) NOT NULL DEFAULT '';
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS name_ar varchar(200) NOT NULL DEFAULT '';
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS name_en varchar(200) NOT NULL DEFAULT '';
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS display_order integer NOT NULL DEFAULT 0;
ALTER TABLE permissions ADD COLUMN IF NOT EXISTS is_sensitive boolean NOT NULL DEFAULT false;
DELETE FROM role_permissions WHERE role_id IN (SELECT role_id FROM roles WHERE role_code='ROLE_USER');
SELECT r.role_id,p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code='ROLE_USER' AND p.is_active=true AND p.permission_code NOT IN ('ACC.FISCAL.ROLL_FORWARD','COMPANY_CREATE','COMPANY_EDIT','COMPANY_DELETE','USER_VIEW','USER_CREATE','USER_EDIT','USER_DELETE','ROLE_VIEW','ROLE_EDIT','PERMISSION_VIEW','ORG.COMPANY.CREATE','ORG.COMPANY.DELETE','ORG.COMPANY.UPDATE','SYS.ADMIN','SYS.PERMISSIONS.VIEW','SYS.PERMISSIONS.MANAGE','SYS.PERMISSION_TEMPLATES.MANAGE','SYS.ROLES.CREATE','SYS.ROLES.DELETE','SYS.ROLES.UPDATE','SYS.ROLES.VIEW','SYS.USERS.CREATE','SYS.USERS.DELETE','SYS.USERS.DISABLE','SYS.USERS.UPDATE','SYS.USERS.VIEW') ON CONFLICT DO NOTHING;
DELETE FROM role_permissions WHERE role_id IN (SELECT role_id FROM roles WHERE role_code='ROLE_VIEWER');
SELECT r.role_id,p.permission_id FROM roles r CROSS JOIN permissions p
WHERE r.role_code='ROLE_VIEWER' AND p.is_active=true AND (p.operation_code='VIEW' OR p.permission_code IN ('SYS.SETTINGS.VIEW','SYS.USERS.VIEW','SYS.ROLES.VIEW','SYS.PERMISSIONS.VIEW','REPORT.VIEW','AUDIT.VIEW','SYSTEM.VIEW')) ON CONFLICT DO NOTHING;
SELECT r.role_id,p.permission_id FROM roles r CROSS JOIN permissions p WHERE r.role_code='ROLE_ADMINISTRATOR' AND p.is_active=true ON CONFLICT DO NOTHING;

